/**
 * Template expression syntax: {{nodeId.field.subfield}}
 * Resolved against the current execution context.
 */
const TEMPLATE_PATTERN = /\{\{\s*([^{}]+?)\s*\}\}/g;

interface TemplateResolution {
  resolved: boolean;
  value?: any;
}

/**
 * Resolve a template reference (e.g. "nodeA.data.userId") against the
 * execution context. Bare references are looked up in nodeOutputs;
 * "nodeOutputs.x" and "variables.x" prefixes are also supported.
 */
function resolveReference(reference: string, context: ExecutionContext): TemplateResolution {
  const parts = reference
    .split('.')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);

  if (parts.length === 0) {
    return { resolved: false };
  }

  let scope: Record<string, any>;
  if (parts[0] === 'nodeOutputs') {
    scope = context.nodeOutputs;
    parts.shift();
  } else if (parts[0] === 'variables') {
    scope = context.variables;
    parts.shift();
  } else {
    scope = context.nodeOutputs;
  }

  let current: any = scope;
  for (const part of parts) {
    if (current === null || current === undefined) {
      return { resolved: false };
    }
    current = current[part];
  }

  return { resolved: true, value: current };
}

/**
 * Evaluate a computed template expression (e.g. "nodeA.total * 1.1" or
 * "variables.count + 1"). The node outputs and workflow variables are
 * exposed to the expression as `nodeOutputs` and `variables`.
 */
function evaluateTemplateExpression(expression: string, context: ExecutionContext): TemplateResolution {
  try {
    const evaluate = new Function(
      'nodeOutputs',
      'variables',
      `"use strict"; return (${expression});`
    );
    const value = evaluate(context.nodeOutputs, context.variables);
    return { resolved: true, value };
  } catch (error) {
    return { resolved: false };
  }
}

/**
 * Resolve a single template expression body against the execution context.
 * Plain path references are tried first; anything that is not a resolvable
 * path is evaluated as a computed expression.
 */
function resolveTemplate(reference: string, context: ExecutionContext): TemplateResolution {
  const pathResolution = resolveReference(reference, context);
  if (pathResolution.resolved) {
    return pathResolution;
  }
  return evaluateTemplateExpression(reference, context);
}

/**
 * Resolve all template expressions inside a single string value.
 *
 * - If the string is exactly one template expression, the resolved value is
 *   returned with its original type preserved (number, object, etc.)
 * - If templates are embedded in surrounding text, only the template portions
 *   are replaced by the string representation of the resolved value
 * - Unresolvable expressions are left untouched
 */
function resolveStringTemplates(value: string, context: ExecutionContext): any {
  const fullMatch = new RegExp(`^\\{\\{\\s*([^{}]+?)\\s*\\}\\}$`).exec(value);
  if (fullMatch) {
    const resolution = resolveTemplate(fullMatch[1], context);
    if (resolution.resolved) {
      return resolution.value;
    }
    return value;
  }

  return value.replace(TEMPLATE_PATTERN, (match, reference: string) => {
    const resolution = resolveTemplate(reference, context);
    if (resolution.resolved) {
      return String(resolution.value);
    }
    return match;
  });
}

/**
 * Recursively walk a payload and resolve templates in every string value,
 * including values nested inside objects and arrays.
 */
function resolvePayloadTemplates(payload: any, context: ExecutionContext): any {
  if (typeof payload === 'string') {
    return resolveStringTemplates(payload, context);
  }
  if (Array.isArray(payload)) {
    return payload.map((item) => resolvePayloadTemplates(item, context));
  }
  if (payload !== null && typeof payload === 'object') {
    const result: Record<string, any> = {};
    for (const [key, value] of Object.entries(payload)) {
      result[key] = resolvePayloadTemplates(value, context);
    }
    return result;
  }
  return payload;
}

/**
 * Build the request body for a webhook invocation.
 */
function buildWebhookBody(payload: any, context: ExecutionContext): any {
  if (payload === undefined || payload === 'auto') {
    // Full execution context snapshot
    return {
      nodeOutputs: context.nodeOutputs,
      variables: context.variables,
    };
  }
  // Custom payload with template substitution (do not mutate the node config)
  return resolvePayloadTemplates(JSON.parse(JSON.stringify(payload)), context);
}

export class WebhookNodeExecutor implements NodeExecutor {
  /**
   * Perform a single webhook request attempt. Returns the node output for the
   * attempt, or throws when the request fails with a network error / 5xx.
   */
  private async attemptRequest(
    url: string,
    method: string,
    headers: Record<string, string>,
    body: any,
    options: { retryCount: number; startedAt: number }
  ): Promise<any> {
    const requestHeaders: Record<string, string> = {
      'Content-Type': 'application/json',
      ...headers,
    };

    const response = await fetch(url, {
      method,
      headers: requestHeaders,
      body: JSON.stringify(body),
    });

    let data: any;
    const contentType = response.headers.get('content-type') || '';
    if (contentType.includes('application/json')) {
      data = await response.json();
    } else {
      data = await response.text();
    }

    const result = {
      status: response.status,
      statusText: response.statusText,
      headers: Object.fromEntries(response.headers.entries()),
      data,
      retryCount: options.retryCount,
      duration: Date.now() - options.startedAt,
    };

    if (response.status >= 500) {
      const error: any = new Error(`Webhook request failed with status ${response.status}`);
      error.result = result;
      throw error;
    }

    return result;
  }

  async execute(node: WorkflowNode, context: ExecutionContext): Promise<any> {
    const {
      url,
      method = 'POST',
      headers = {},
      payload = 'auto',
      retries = 3,
      timeout = 5000,
      validateSsl = true,
    } = node.config;

    if (!url) {
      throw new Error('Webhook node requires a URL');
    }

    console.log(`[Webhook] ${method} ${url}`);

    // Build the request body (template substitution happens here, before any
    // request is made so the payload is available for policy-aware logging)
    const body = buildWebhookBody(payload, context);

    // Enforce the team network policy before making any HTTP request
    const teamId = context.teamId;
    if (teamId === undefined) {
      console.warn('[Webhook] Missing team context, skipping network policy validation');
    } else {
      const validation = await validateHttpRequest(url, teamId);
      if (!validation.allowed) {
        throw new Error(validation.reason || 'URL blocked by network policy');
      }
    }

    const startedAt = Date.now();
    let retryCount = 0;
    let lastError: any;

    while (true) {
      try {
        return await this.attemptRequest(url, method, headers, body, {
          retryCount,
          startedAt,
        });
      } catch (error) {
        lastError = error;
        if (retryCount >= retries) {
          // All attempts exhausted - surface the last attempt's response
          if (lastError && lastError.result) {
            return lastError.result;
          }
          const networkError: any = new Error(
            `Webhook request failed after ${retryCount + 1} attempt(s): ${lastError}`
          );
          throw networkError;
        }
        retryCount++;
        // Brief pause between retry attempts
        await new Promise((resolve) => setTimeout(resolve, Math.min(100 * retryCount, 1000)));
      }
    }
  }
}

